#pragma once

#include "util.h"
#include <iostream>

namespace ws {

class Buffer;

namespace io {

class IReader {
public:
    virtual ~IReader() = default;
    virtual std::size_t ReadFrom(Buffer& buf) = 0;
};

class IWriter {
public:
    virtual ~IWriter() = default;
    virtual std::size_t WriteTo(Buffer& buf) = 0;
};

class IReadWriter : public IReader, public IWriter {
public:
    virtual ~IReadWriter() = default;
};

class Null : public IReadWriter {
public:
    std::size_t WriteTo(Buffer& buf) noexcept override;
    std::size_t ReadFrom(Buffer& buf) noexcept override;
};

class StringStream : public IReadWriter {
    std::istream& read_;
    std::ostream& write_;
public:
    explicit StringStream(std::istream& read, std::ostream& write) noexcept
        : read_(read), write_(write) {}
    std::size_t WriteTo(Buffer& buf) noexcept override;
    std::size_t ReadFrom(Buffer& buf) noexcept override;
};

class FileDescriptor : public IReadWriter {
    ws::FileDescriptor read_;
    ws::FileDescriptor write_;
public:
    explicit FileDescriptor(ws::FileDescriptor read, ws::FileDescriptor write) noexcept
        : read_(read), write_(write) {}
    std::size_t WriteTo(Buffer& buf) override;
    std::size_t ReadFrom(Buffer& buf) override;
};

}  // namespace io

}  // namespace ws

#include "io.h"
#include "containers/buffer.h"
#include <sys/uio.h>
#include <unistd.h>
#include <array>

namespace ws::io {

std::size_t Null::WriteTo(Buffer& buf) noexcept {
    const auto size = buf.WritableSize();
    buf.HasWritten(size);
    return size;
}

std::size_t Null::ReadFrom(Buffer& buf) noexcept {
    const auto size = buf.RetrieveAll();
    return size;
}

std::size_t StringStream::WriteTo(Buffer& buf) noexcept {
    std::string line;
    if (!std::getline(read_, line)) {
        return 0;
    }
    const auto size = line.size();
    buf.Append(line.data(), size);
    return size;
}

std::size_t StringStream::ReadFrom(Buffer& buf) noexcept {
    const auto size = buf.ReadableSize();
    if (size == 0) {
        return 0;
    }
    write_.write(buf.Peek(), size);
    buf.Retrieve(size);
    return size;
}

std::size_t FileDescriptor::WriteTo(Buffer& buf) {
    const auto writable = buf.WritableBytes();
    if (writable.size() == 0) {
        return 0;
    }

    std::array<char, 0x10000> ext_bytes{};
    iovec vec[2];
    vec[0].iov_base = const_cast<char*>(writable.data());
    vec[0].iov_len = writable.size();

    ssize_t size;
    if (writable.size() < 0x10000) {
        size = readv(read_.fd(), vec, 1);
    } else {
        vec[1].iov_base = ext_bytes.data();
        vec[1].iov_len = ext_bytes.size();
        size = readv(read_.fd(), vec, 2);
    }

    if (size < 0) {
        ThrowLastSystemError("readv failed");
    }

    const auto written = std::min(static_cast<size_t>(size), writable.size());
    buf.HasWritten(written);

    if (static_cast<size_t>(size) > writable.size()) {
        const auto remaining = static_cast<size_t>(size) - writable.size();
        buf.Append(ext_bytes.data(), remaining);
    }

    return size;
}

std::size_t FileDescriptor::ReadFrom(Buffer& buf) {
    const auto readable = buf.ReadableBytes();
    if (readable.empty()) {
        return 0;
    }

    ssize_t size = write(write_.fd(), readable.data(), readable.size());
    if (size < 0) {
        ThrowLastSystemError("write failed");
    }

    buf.Retrieve(size);
    return size;
}

}  // namespace ws::io
